@startuml

class Student {
  + studentId : string
  + dateOfBirth : date
  + city : string
  + region : string
  + yearOfEnrollment : int
}

class Professor {
  + name : string
  + dateOfBirth : date
  + city : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : string
  + lectureHours : int
}

class Exam {
  + grade : string
}

Student "1" -- "1" Faculty : enrolled_in
Professor "1..*" -- "1" Faculty : belongs_to
Professor "1..*" -- "*" Course : teaches
Course "1" -- "*" Exam : part_of
Student "1" -- "*" Exam : passes

@enduml

